        symbol = player.symbol
        for i in range(self.size):
            for j in range(self.size):
                if (np.all(self.board[i, j, :] == symbol) or
                    np.all(self.board[i, :, j] == symbol) or
                    np.all(self.board[:, i, j] == symbol)):
