```python
import random

class Game:
    def __init__(self, rows=50, cols=50):
        self.rows = rows
        self.cols = cols
        self.board = [[0] * cols for _ in range(rows)]

    def initializeBoard(self, randomize=True):
        if randomize:
            for i in range(self.rows):
                for j in range(self.cols):
                    self.board[i][j] = random.choice([0, 1])

    def calculateNextGeneration(self):
        newBoard = [[0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(self.cols):
                newBoard[i][j] = self.nextCellState(i, j)
        self.board = newBoard

    def nextCellState(self, row, col):
        aliveNeighbors = 0
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                newRow, newCol = row + i, col + j
                if 0 <= newRow < self.rows and 0 <= newCol < self.cols:
                    aliveNeighbors += self.board[newRow][newCol]
        return 1 if self.board[row][col] and 2 <= aliveNeighbors <= 3 or not self.board[row][col] and aliveNeighbors == 3 else 0

    def getBoard(self):
        return self.board
```

