Here is a Python implementation of a solvable labyrinth:

```python
import random

class Cell:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.visited = False
        self.neighbors = []

class Labyrinth:
    def __init__(self, width, height):
        self.cells = []
        for x in range(width):
            row = []
            for y in range(height):
                cell = Cell(x, y)
                row.append(cell)

    def generate(self):
        for cell in self.cells:
            cell.visited = False
        for cell in self.cells:
            if not cell.visited:
                self._generate(cell)

    def _generate(self, cell):
        cell.visited = True
        for neighbor in cell.neighbors:
            if not neighbor.visited:
                self._generate(neighbor)

    def display(self):
        for row in self.cells:
            for cell in row:
                if cell.visited:
                    print('X', end='')
                else:
                    print('.', end='')
            print()

    def solve(self):
        def _solve(cell):
            if cell.visited:
                return False
            cell.visited = True
            for neighbor in cell.neighbors:
                if not neighbor.visited and _solve(neighbor):
                    return True
            return False
        return _solve(self.cells[0])

def main():
    labyrinth = Labyrinth(10, 10)
    labyrinth.generate()
    labyrinth.display()
    print('Path found:', labyrinth.solve())

if __name__ == '__main__':
    main()
