use std::collections::HashMap;

impl Solution {
    pub fn super_egg_NAME_2(k: i32, n: i32) -> i32 {
        let mut memo = HashMap::new();

        fn dp(eggs: i32, floors: i32, memo: &mut HashMap<(i32, i32), i32>) -> i32 {
            if let Some(&drops) = memo.get(&(eggs, floors)) {
                return drops;
            }

            if floors == 0 {
                return 0;
            }

            if eggs == 1 {
                return floors;
            }

            let mut min_drops = i32::MAX;
            for f in 1..=floors {
                let drops = 1 + std::cmp::max(
                    dp(eggs - 1, f - 1, memo), 
                    dp(eggs, floors - f, memo)
                );
                min_drops = min_drops.min(drops);
            }

            memo.insert((eggs, floors), min_drops);
            min_drops
        }

        dp(k, n, &mut memo)
    }
}
```

The key differences from Python:

- Use a HashMap instead of a dict for memoization
- Recursive function dp() instead of inner dp()
- Rust doesn't have default args, so memo needs to be passed explicitly 
- Use std::cmp::max instead of built-in max
- Use i32 instead of int for fixed size integers

The overall bottom-up DP approach remains the same.

