impl Solution {
    pub fn max_run_time(n: i32, batteries: Vec<i32>) -> i64 {
        let mut total = 0;
        for &b in &batteries {
            total += b;
        }

        let mut batteries = batteries;
        batteries.sort_by_key(|&b| Reverse(b));

        let mut curr = 0;
        let mut ans = 0;

        for i in 0..n {
