Here is one possible implementation of the `queueToList` function in C:
```c
#include <stdio.h>
#include <stdlib.h>

struct list {
    int val;
    struct list *next;
};

struct queue {
    int val;
    struct queue *next;
    struct queue *prev;
};

struct list *queueToList(struct queue *q) {
    struct list *result = NULL;
    struct queue *current = q;
    while (current != NULL) {
        struct list *newList = malloc(sizeof(struct list));
        newList->val = current->val;
        newList->next = NULL;
        if (result == NULL) {
            result = newList;
        } else {
            struct list *temp = result;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newList;
        }
        current = current->next;
    }
    return result;
}

int main() {
    struct queue q;
    q.val = 1;
    q.next = 4;
    q.prev = NULL;

    struct list *lst = queueToList(&q);
    printf("List: ");
    for (struct list *i = lst; i != NULL; i = i->next) {
        printf("%d ", i->val);
    }
    printf("\n");

    q.val = 8;
    lst = queueToList(&q);
    printf("List: ");
    for (struct list *i = lst; i != NULL; i = i->next) {
        printf("%d ", i->val);
    }
    printf("\n");

    return 0;
