```python
def binary_tree_search(root, value, stack=None):
    """
    Searches for a value in a binary tree using a stack.

    Parameters:
    root (Node): The root of the binary tree.
    value (any): The value to search for.
    stack (List[any]): An optional stack to use. If None, a new stack will be created.

    Returns:
    any: The matching node or None if not found.
    """
    if root is None:
        return None
    if root.value == value:
        return root
    if value < root.value:
        if stack is None:
            stack = []
        stack.append(root)
        while stack:
            current_node = stack[-1]
            if current_node.left:
                stack.append(current_node.left)
            if current_node.right:
                stack.append(current_node.right)
            if current_node.value == value:
                return current_node
        return None
    else:
        if stack is None:
            stack = []
        stack.append(root)
        while stack:
            current_node = stack[-1]
            if current_node.left:
                stack.append(current_node.left)
            if current_node.right:
                stack.append(current_node.right)
        return None
```

