```js
const notes = {
    'C': 1,
    'C#': 2**(1/12), 
    'D': 2**(2/12),
    'D#': 2**(3/12),
    'E': 2**(4/12),
    'F': 2**(5/12),
    'F#': 2**(6/12),
    'G': 2**(7/12),
    'G#': 2**(8/12),
    'A': 2**(9/12),
    'A#': 2**(10/12),
    'B': 2**(11/12) 
}

function generateNote(freq) {
    const noteName = Object.keys(notes).find(note => notes[note] === freq);
    return noteName; 
}

function justIntonation(rootNote, interval) {
    const rootFreq = notes[rootNote];
    const intervalRatio = notes[interval];
    return rootFreq * intervalRatio; 
}

function playScale(rootNote, scale) {
    let audioCtx = new AudioContext();
    for (let interval of scale) {
        const freq = justIntonation(rootNote, interval);
        const noteName = generateNote(freq);
        console.log(noteName);
