import queue

class RpcJsonServer:
    def __init__(self, host='localhost', port=8000):
        self.host = host
        self.port = port
        self.server = None
        self.running = False
        self.queue = queue.Queue()

    def start(self):
        self.server = jsonrpc.Server(self.queue)
        self.server.add_handler(self.handle_request, name='/echo')
        self.server.start()
        self.running = True

    def handle_request(self, request):
        if request['function'] == '/echo':
            response = {
                'result': request['params']['text'] + ' (from server)'
            }
        else:
            response = {
                'error': 'Invalid function'
            }
        return response

    def stop(self):
        self.running = False
        self.server.stop()

if __name__ == '__main__':
