```python
def risk_factor(G, u):
    def count_paths(G, v):
        count = 0
        for w in G:
            if w != v and (w, v) not in G.edges():
                count += 1
        return count

    def dfs(G, v, visited):
        visited.add(v)
        for w in G[v]:
            if w not in visited:
                dfs(G, w, visited)

    visited = set()
    count = 0
    for v in G:
        if v != u and v not in visited:
            dfs(G, v, visited)
            count += count_paths(G, v)
    return count

