```python
def limit(f, a, b):
    if b == 0:
        return "The limit of " + f + " as " + a + " approaches 0 is " + str(float('inf'))
    elif a == 0:
        return "The limit of " + f + " as " + b + " approaches 0 is " + str(float('-inf'))
    else:
        delta = (b - a) / 2
        return "The limit of " + f + " as " + a + " approaches " + str(b) + " is " + str(f(b - delta))

# Example usage
print(limit(x, 1, 3)) # The limit of x as 1 approaches 3 is 3
print(limit(sin, 0, 2)) # The limit of sin as 0 approaches 2 is -2
```
