import tkinter as tk
import snake
import food

class Game:
    def __init__(self, root, difficulty=1):
        self.root = root
        self.canvas = tk.Canvas(root, width=500, height=500, bg='black')
        self.canvas.pack()
        self.snakeObj = snake.Snake(self.canvas, difficulty)
        self.foodObj = food.Food(self.canvas, self.snakeObj, difficulty)
        self.score = 0
        self.gameOver = False
        self.paused = False
        self.difficulty = difficulty
        self.updateGameState()

    def handleKeyPress(self, event):
        key = event.keysym
        if key in ('Up', 'Down', 'Left', 'Right'):
            self.snakeObj.changeDirection(key)
        elif key == 'p':
            self.pauseGame()

    def updateGameState(self):
        if not self.gameOver and not self.paused:
            self.snakeObj.move()
            head = self.snakeObj.body[0]
            if self.snakeObj.checkCollision() or any(segment == head for segment in self.snakeObj.body[1:]):
                self.gameOver=True
            elif self.checkFoodCollision():
                self.snakeObj.grow()
                self.foodObj.newFood()
                self.score += 1
        self.root.after(self.getUpdateInterval(), self.updateGameState)

    def getUpdateInterval(self):
        baseInterval = 200
