def get_common_sentences(list1, list2):
    l1, l2 = len(list1), len(list2)
    lcs = [[0] * (l2 + 1) for _ in range(l1 + 1)]
    for i in range(l1):
        for j in range(l2):
            if list1[i] == list2[j]:
                lcs[i+1][j+1] = lcs[i][j] + 1
            else:
                lcs[i+1][j+1] = max(lcs[i][j+1], lcs[i+1][j])

    result = []
    i, j = l1, l2
    while i > 0 and j > 0:
        if lcs[i][j] == lcs[i-1][j-1] + 1:
            result.append(list1[i-1])
            i -= 1
            j -= 1
        elif lcs[i-1][j] > lcs[i][j-1]:
            i -= 1
        else:
            j -= 1
    return result[::-1] 
