{
    public ItemsManager(int slots)
    {
        ValidateSlots(slots);
        Slots = slots;
        _items = new List<T>();
    }

    private const int MinimumSlots = 1;
    private const int MaximumSlots = 64;

    public IEnumerable<T> Items => FilterItems(null);
    private bool HasEmptySlot => _items.Count < Slots;

    public int Slots { get; }
    private readonly List<T> _items;

    public void AddItem(T item)
    {
        if (!HasEmptySlot) throw new InvalidOperationException("All slots are occupied.");

        _items.Add(item);
    }

    public void AddItems(IEnumerable<T> items)
    {
        foreach (T item in items)
        {
            try
            {
                AddItem(item);
            }
            catch (InvalidOperationException)
            {
                throw new InvalidOperationException("There were not enough empty slots to accomodate all items, only some of them have been added.");
            }
        }
    }

    public void RemoveItem(T item)
    {
        if (!_items.Contains(item)) throw new InvalidOperationException($"The item {item} is not present and can't be removed.");

        _items.Remove(item);
    }

    public IEnumerable<T> FilterItems(Func<T, bool>? filter)
    {
        return _items.Where(filter ?? (_ => true));
    }

    private static void ValidateSlots(int slots)
    {
        if (slots is < MinimumSlots or > MaximumSlots)
        {
            throw new ArgumentException($"Incorrect number of slots, must be betwe

end MinimumSlots and MaximumSlots, but was {slots}.");
        }
    }
}

public static class ItemsManagerExtensions
{
    public static ItemsManager<T> Create<T>(this int slots)
    {
        return new ItemsManager<T>(slots);
    }
}
