import heapq

def heappush(heap, item):
    heapq.heappush(heap, item)

def heappop(heap):
    return heapq.heappop(heap)

def heappush_or_update(heap, node, distance):
    if node not in heap:
        heappush(heap, (distance, node))
    else:
        heapq.heappush(heap, (distance, node))

def get(heap, node):
    for distance, _ in heap:
        if distance == node:
            return distance
    return float('inf')

def shortest_path_length(graph, start, destination):
    visited = set()
    unknown_points = [(0, start)]
    distance_map = {start: 0}

    while unknown_points:
        _, current = heappop(unknown_points)
        if current == destination:
            return distance_map[current]

        for successor in graph[current]:
            if successor not in visited and successor not in distance_map:
                new_distance = distance_map[current] + graph[current][successor]
                heappush_or_update(unknown_points, successor, new_distance)
                distance_map[successor] = new_distance
            visited.add(successor)

    return float('inf')

