```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.items:
            raise ValueError('Stack is empty')
        return self.items.pop()

    def peek(self):
        if not self.items:
            raise ValueError('Stack is empty')
        return self.items[-1]

    def is_balanced(self):
        if not self.items:
            return True
        if self.peek() != '(':
            return False
        if not self.pop():
            return False
        if self.is_balanced():
            return True
        if self.peek() != ')':
            return False
        if not self.pop():
            return False
        return self.is_balanced()

def main():
    stack = Stack()
    stack.push('(')
    stack.push('a')
    stack.push('b')
    stack.push('c')
    stack.push('d')
    stack.push(')')
    print(stack.is_balanced()) # should print True
    stack.pop() # should not raise an error
    print(stack.is_balanced()) # should print False
if __name__ == '__main__':
    main()
```
