def next_palindrome(num_list):
    if not num_list:
        return [1] + [0] * (len(num_list) + 1)

    middle = len(num_list) // 2
    smaller_list = num_list[:middle]
    larger_list = num_list[middle:]

    while larger_list:
        if smaller_list[-1] == larger_list[0]:
            smaller_list.pop()
            larger_list.pop(0)
        elif larger_list[0] == larger_list[-1]:
            larger_list.pop(0)
