import random

def tictactoe(board):
    # Check if there is a winner
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != " ":
            if board[i][0] == "X":
                return "X"
            else:
                return "O"

    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] != " ":
            if board[0][j] == "X":
                return "X"
            else:
                return "O"

