    freq = {}
    # Iterate through the string
    for i in range(len(s)):
        # Check if the current character is in the dictionary
        if s[i] in freq:
            # If the frequency is even, remove the character
            if freq[s[i]] & 0x01 == 0:
                freq[s[i]] = 0
