class Parser:
    def __init__(self):
        self.stack = []

    def parse(self, expression):
        self.stack = [token for token in expression.split()]
        self.stack.reverse()

        while self.stack:
            tok = self.stack.pop()
            if tok == '(':
                self.stack.append(tok)
                continue
            elif tok == ')':
                while self.stack and self.stack[-1] != '(':
                    op = self.stack.pop()
                    right = self.stack.pop()
                    if op == '+':
                        self.stack.append(right)
                    elif op == '-':
                        self.stack.append(-right)
                    elif op == '*':
                        self.stack.append(right)
                    elif op == '/':
                        self.stack.append(right)
                continue
            elif tok.isdigit():
                continue
            elif tok == '+':
                right = self.stack.pop()
                self.stack.append(right)
            elif tok == '-':
                right = self.stack.pop()
                self.stack.append(-right)
            elif tok == '*':
                right = self.stack.pop()
                self.stack.append(right)
            elif tok == '/':
                right = self.stack.pop()
                self.stack.append(right)
            else:
                raise ValueError(f"Invalid token: {tok}")

        return ' '.join(self.stack)

