Here's an example implementation of memoized coin change function in Python:
```python
def coin_change(amount, coins):
    # Check if the amount is negative or zero
    if amount < 0 or amount == 0:
        return []

    # Check if the amount can be formed using the given coins
    if amount not in denominations:
        return None

    # Initialize the memoization dictionary
    cache = {}

    # Use dynamic programming to calculate the coin change
    coin_changes = []
    for coin in coins:
        for amt in range(coin, amount + 1):
            if amt not in cache:
                cache[amt] = coin_change(amt, coins)
            if cache[amt] is not None:
                coin_changes.append((coin, amt))

    # If the amount is not positive, return None
    if amount < 0:
        return None

    # Sort the coin changes by coin value and amount
    coin_changes.sort(key=lambda x: (-x[0], x[1]))

    # Combine the coin changes and return the result
    result = []
    for coin, amount in coin_changes:
        for coin_denom, coin_amt in coin_changes:
            if coin_denom == coin and amount + coin_amt >= amount:
                amount -= coin_amt
                result.append((coin, coin_amt))
                break
        else:
            result.append((coin, amount))

    return result
```
