def minimum_spanning_tree(edges):
    def bisect_dict(a, b):
        if a < b:
            return a, b
        else:
            return b, a

    def find_divide_point(edges, x):
        y = x
        while y in edges:
            y = bisect_dict(y, x)
        return y

    def add_edge_to_tree(x, y, tree):
        if x not in tree or y not in tree:
            tree[x].add(y)
            tree[y].add(x)

    def process_edge(x, y, visited, edges):
        if x not in visited or y not in visited:
            visited[x].add(y)
            visited[y].add(x)
            for z in visited[x]:
                add_edge_to_tree(z, y, visited[x][y])
            for z in visited[y]:
                add_edge_to_tree(x, z, visited[y][x])
            edges = [e for e in edges if e[0] != x or e[1] != y]
            process_edge(find_divide_point(edges, x), find_divide_point(edges, y), visited, edges)

    visited = {}
    for x in range(len(edges)):
        visited[x] = set([x])

    for e in edges:
        process_edge(*e, visited, edges)

    tree = {}
    for x in range(len(edges)):
        tree[x] = set([x])
    for x, y in edges:
        add_edge_to_tree(x, y, tree[x])
        add_edge_to_tree(y, x, tree[y])

    return tree

