import heapq
from collections import defaultdict

def weight(a, b):
    return 1 if a == b else 2

def shortest_path_length(line_length, start, destination):
    graph = defaultdict(float)
    for a, b in line_length:
        graph[a, b] = weight(a, b)
    distances = defaultdict(float)
    queue = [(start, 0)]

    while queue:
        node, current_distance = heapq.heappop(queue)
        if node == destination:
            return current_distance
        for neighbor, weight in graph[node].items():
            new_distance = current_distance + weight
            if neighbor not in distances:
                distances[neighbor] = new_distance
            else:
                distances[neighbor] = min(distances[neighbor], new_distance)
            heapq.heappush(queue, (neighbor, new_distance))
    return float('inf')

def get(unknown_points, target_node):
    return unknown_points[target_node]

def insert_or_update(node_pile, target_node):
    if target_node not in node_pile:
        node_pile[target_node] = (target_node, 0)
    else:
        node_pile[target_node] = heapq.heappop(node_pile)[1] + 1

def main():
    line_length = {("A", "B"): 1, ("B", "C"): 2, ("C", "D"): 1, ("D", "A"): 2}
    start = "A"
    destination = "D"

    unknown_points = defaultdict(float)
    insert_or_update(unknown_points, start)

    current_distance = 0
    current_node = start
    while destination not in unknown_points:
        for neighbor, weight in line_length[current_node].items():
            new_distance = current_distance + weight
            if neighbor not in unknown_points:
                unknown_points[neighbor] = new_distance
            else:
                unknown_points[neighbor] = min(unknown_points[neighbor], new_distance)
        current_distance += 1
        current_node = heapq.heappop(unknown_points)[0]

    return current_distance

if __name__ == "__main__":
    result = main()
    print(f"The shortest path length from {start} to {destination} is {result}.")
```
This program uses a Fibonacci heap to keep track of the shortest distances from the start node to all visited nodes. The main loop continues until the destination node is reached, and the shortest path length is returned. If the destination node is not reached, float('inf') is returned, indicating that no path was found.

