```python
import sys

def print_primes(start, end=100, separator=None):
    for num in range(start, end+1):
        if num > 1:
            for divisor in range(2, num):
                if num % divisor == 0:
                    break
            else:
                print(num, end="")
        else:
            print(num, end="")
        if separator is not None and num > 1:
            print(separator, end="")
        if num > 1 and num % 10 == 0:
            print()

if len(sys.argv) > 1:
    start = int(sys.argv[1])
    end = int(sys.argv[2])
    separator = '-' if sys.argv[3] == '-s' else ' '
    print_primes(start, end, separator)
else:
    print_primes(1, 100)
```
