class WeightedGraph:
    def __init__(self):
        self.adj_list = {}

    def add_edge(self, u, v, weight):
        if u not in self.adj_list:
            self.adj_list[u] = []
        self.adj_list[u].append((v, weight))

    def shortest_path_length(self, start, end):
        if start not in self.adj_list or end not in self.adj_list:
            return float('inf')

        dist = [0] * (len(self.adj_list) + 1)
        dist[0] = float('inf')
        dist[start] = 0

        queue = FibonacciHeap()
        visited = set()

        while queue:
            u, v = queue.pop()
            if v in visited:
                continue

            visited.add(v)
            for next, weight in self.adj_list[u]:
                alt = dist[u] + weight
                if v in self.adj_list and alt < dist[v]:
                    dist[v] = alt
                    queue.insert_or_update(v, alt)

        return dist[end]

class FibonacciHeap:
    def __init__(self):
        self.heap = []

    def get(self, index):
        return self.heap[index]

    def insert_or_update(self, u, alt):
        if u not in self.heap:
            self.heap.append(u)
        else:
            self.heap[self.heap.index(u)] = alt

