                current_digit += 1
            else:
                self.right_digits.append(current_digit)
        if current_digit!= 0:
            self.right_digits.append(current_digit)

    def check_palindrome(self):
        if self.left_digits!= [] and self.right_digits!= [] and self.left_digits == self.right_digits:
            return True
        else:
            return False
