```python
import heapq

def shortest_path_length(line_length, start, destination):
    n = len(line_length)
    if n == 0:
        return float('inf')

    unknown_points = [(start, 0)]
    dist_cache = {start: 0}

    while unknown_points:
        min_point = heapq.heappop(unknown_points)
        node, dist = min_point

        if node == destination:
            return dist

        if dist > dist_cache.get(node, float('inf')):
            continue

        for i in range(n):
            if i != node and i < n - 1:
                new_dist = dist + line_length[node][i] + line_length[i][node]
                if new_dist < dist_cache.get(i, float('inf')):
                    dist_cache[i] = new_dist
                    heapq.heappush(unknown_points, (i, new_dist))

    return float('inf')

def get(unknown_points, target_node):
    for node, dist in unknown_points:
        if node == target_node:
            return dist
    return float('inf')

def insert_or_update(node_pile, target_node):
    for node, dist in node_pile:
        if node == target_node:
            return node, dist

    node_pile.append((target_node, dist))
    return node_pile[-1]

# Example usage
line_length = [
    [0, 1, 2],
    [10, 11, 12],
    [20, 21, 22]
]
start = 0
destination = 2

shortest_path_length_result = shortest_path_length(line_length, start, destination)
print(f"Shortest path length: {shortest_path_length_result}")
```
